custom_css:
/* Claude Surface: Light. CSS-only mode preserves the native toolbar. */
body {
    --cu-bg: #fff;
    --cu-sidebar: #f8f8f8;
    --cu-input: #fff;
    --cu-surface: #fff;
    --cu-hover: #00000008;
    --cu-selected: #0000000d;
    --cu-text: #000000e6;
    --cu-muted: #0009;
    --cu-border: #0000001f;
    --cu-input-border: #0000001f;
    --cu-user: #00000005;
    --cu-code: #f8f8f8;
    --cu-link: #245c9b;
    --cu-syntax-keyword: #8b4098;
    --cu-syntax-string: #447537;
    --cu-syntax-title: #825d17;
    --cu-syntax-number: #ac6b2a;
    --cu-syntax-comment: #6b6b6b;
    --cu-overlay: #0006;
    color-scheme: light;
}

body {
    --cu-accent: #d77757;
    --cu-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
    --cu-serif: Georgia, "Times New Roman", var(--cu-sans);
    --cu-sidebar-width: 280px;
    --cu-header: 48px;
    --cu-native-height: 42px;
    --cu-bottom-inset: 0px;
    --cu-panel-top: 56px;
    --cu-panel-max-height: calc(100dvh - var(--cu-panel-top) - 12px);
    --SmartThemeBodyColor: var(--cu-text);
    --SmartThemeEmColor: var(--cu-muted);
    --SmartThemeBlurTintColor: var(--cu-surface);
    --SmartThemeChatTintColor: var(--cu-bg);
    --SmartThemeUserMesBlurTintColor: var(--cu-user);
    --SmartThemeBotMesBlurTintColor: transparent;
    --SmartThemeBorderColor: var(--cu-border);
    --SmartThemeShadowColor: transparent;
    --SmartThemeQuoteColor: var(--cu-link);
    --SmartThemeUnderlineColor: var(--cu-accent);
    --mainFontSize: 15px;
    --mainFontFamily: var(--cu-sans);
    font-family: var(--cu-sans);
    font-size: 15px;
    color: var(--cu-text);
    background: var(--cu-bg) !important;
    text-shadow: none !important;
}
body #bg1, body #bg_custom { opacity: 0; pointer-events: none; }
body.cu-shell-ready #top-bar { display: none; }
body.cu-background-enabled #bg1, body.cu-background-enabled #bg_custom { opacity: 1; }
body.cu-background-enabled :is(#sheld,#chat) { background: transparent !important; }
body * { text-shadow: none !important; scrollbar-width: thin; scrollbar-color: var(--cu-border) transparent; }
body button, body input, body textarea, body select { font-family: var(--cu-sans); }
body :focus-visible { outline: 2px solid var(--cu-muted) !important; outline-offset: -3px; }
body :is(input:not([type="checkbox"]):not([type="radio"]):not([type="range"]),textarea,select):not(#send_textarea):not(#curEditTextarea):is(:focus,:focus-visible) {
    outline: none !important; border-color: var(--cu-muted) !important; box-shadow: inset 0 0 0 1px var(--cu-muted) !important;
}
body :is(#send_textarea,#curEditTextarea):focus-visible { outline: none !important; box-shadow: none !important; }
body .select2-container--focus .select2-selection { outline: none !important; border-color: var(--cu-muted) !important; box-shadow: inset 0 0 0 1px var(--cu-muted); }
body .select2-selection .select2-search__field:is(:focus,:focus-visible) { border-color: transparent !important; box-shadow: none !important; }
body a { color: var(--cu-link); }
body #sheld {
    position: fixed !important;
    inset: var(--cu-header) 0 var(--cu-bottom-inset) !important;
    width: 100% !important;
    max-width: none !important;
    height: calc(100dvh - var(--cu-header) - var(--cu-bottom-inset)) !important;
    margin: 0 !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    background: var(--cu-bg) !important;
    display: flex;
    flex-direction: column;
    min-height: 0;
    transform: none !important;
    backdrop-filter: none;
}
body #sheldheader { display: none; }
body #chat {
    flex: 1 1 auto;
    min-height: 0;
    width: 100%;
    max-height: none !important;
    padding: 24px max(24px, calc((100% - 720px) / 2)) 40px !important;
    background: var(--cu-bg) !important;
    border: 0 !important;
    box-shadow: none !important;
    overflow-x: hidden;
    overflow-y: auto;
    align-items: stretch;
    scroll-padding: 20px;
}
body #chat .mes {
    position: relative;
    width: 100%;
    min-width: 0;
    display: flex;
    flex-wrap: nowrap;
    padding: 0;
    margin: 0 0 26px;
    gap: 10px;
    border: 0 !important;
    border-radius: 0;
    background: transparent !important;
    box-shadow: none !important;
    backdrop-filter: none;
}
body #chat .mes_block { width: 100%; min-width: 0; padding: 0; display: flex; flex-direction: column; }
/* Keep every native message control, while placing the small avatar and swipe
   controls below the message instead of consuming the reading column. */
body #chat .mes { display: block; padding-bottom: 2px; }
body #chat .mes .for_checkbox { position: absolute; }
body #chat .mes .del_checkbox { position: absolute; top: 10px; left: -16px; }
body #chat .mes_text { padding: 0; font-family: var(--cu-serif); font-size: 16px; line-height: 1.65; color: var(--cu-text); overflow-wrap: anywhere; }
body #chat .mes_text p { margin: 0 0 1em; }
body #chat .mes_text p:last-child { margin-bottom: 0; }
body #chat .mes_text { font-weight: 400; }
body #chat .mes_text strong { font-weight: 600; }
body #chat .mes_text :is(h1,h2,h3,h4) { color: var(--cu-text); font-size: 1.15em; line-height: 1.45; margin: 1.4em 0 .6em; }
body #chat .mes[is_user="true"] { max-width: 88%; margin-left: auto; }
body #chat .mes[is_user="true"] .mes_text { font-family: var(--cu-sans); font-size: 15px; line-height: 1.5; background: var(--cu-user); padding: 12px 16px; border-radius: 12px; }
body #chat .ch_name { order: 10; min-height: 28px; margin: 8px 0 0; align-items: center; font-size: 11px; color: var(--cu-muted); gap: 8px; }
body #chat .ch_name .name_text { font-size: 11px; font-weight: 400; color: var(--cu-muted); }
body #chat .mes_buttons { opacity: .7; gap: 8px; }
body #chat .mes_buttons:hover { opacity: 1; }
body #chat .mes_button { color: var(--cu-muted); font-size: 13px; padding: 5px; border-radius: 6px; }
body #chat .mes_button:hover { color: var(--cu-text); background: var(--cu-hover); }
body #chat .mes_buttons .mes_button { opacity: 1; }
body #chat .extraMesButtons { flex-wrap: wrap; }
body #chat .mes_edit_buttons { flex-wrap: wrap; gap: 5px; }
body #chat .mesAvatarWrapper { flex: 0 0 24px; width: 24px; opacity: .8; }
body #chat .mes .mesAvatarWrapper { position: absolute; bottom: 4px; left: 0; height: 24px; padding: 0; }
body #chat .mes .ch_name { margin-left: 32px; margin-right: 64px; min-height: 28px; }
body #chat .avatar { width: 24px; height: 24px; border-radius: 50%; background: var(--cu-selected); }
body #chat .avatar img { width: 100%; height: 100%; object-fit: cover; box-shadow: none; }
body #chat .mesIDDisplay, body #chat .mes_timer, body #chat .tokenCounterDisplay { font-size: 9px; color: var(--cu-muted); }
body #chat .swipe_left, body #chat .swipeRightBlock { position: static; align-self: flex-end; font-size: 12px; color: var(--cu-muted); flex-shrink: 0; }
body #chat .mes .swipe_left { position: absolute; bottom: 3px; right: 32px; width: 24px; height: 24px; }
body #chat .mes .swipeRightBlock { position: absolute; bottom: 0; right: 0; width: 28px; margin: 0; }
body #chat .mes .swipe_right { font-size: 14px; height: 20px; }
body #chat .mes .swipes-counter { font-size: 10px; }
/* A real footer grid reserves space for the avatar, metadata and actions in both
   viewing and editing states; no avatar is positioned over changing text. */
body #chat .mes .ch_name {
    display: grid;
    grid-template-columns: 24px minmax(0,1fr);
    grid-template-rows: minmax(24px,auto) minmax(28px,auto);
    align-items: start;
    gap: 4px 8px;
    width: 100%;
    max-width: 100%;
    margin: 10px 0 0;
    padding: 0 56px 0 0;
    font-weight: 400;
}
body #chat .mes .ch_name > .mesAvatarWrapper {
    position: static;
    grid-column: 1;
    grid-row: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    align-self: start;
    width: 24px;
    height: auto;
    min-height: 24px;
    padding: 0;
    margin: 0;
}
body #chat .mes.smallSysMes:not(:has(.edit_textarea)) .ch_name { display: none; }
body.documentstyle #chat .mes .ch_name > .mesAvatarWrapper { display: none; }
body #chat .mes .ch_name > .flex-container.flex1 { grid-column: 2; grid-row: 1; min-width: 0; width: 100%; }
body #chat .ch_name .alignItemsBaseline { flex-wrap: wrap; min-width: 0; gap: 2px 6px; }
body #chat .ch_name .name_text { white-space: normal; overflow-wrap: anywhere; max-width: 100%; line-height: 16px; }
body #chat .ch_name .timestamp { font-size: 10px; line-height: 16px; white-space: normal; }
body #chat .ch_name :is(.mes_buttons,.mes_edit_buttons) {
    grid-column: 1 / -1;
    grid-row: 2;
    justify-self: start;
    align-self: start;
    flex-wrap: wrap;
    align-items: center;
    width: max-content;
    max-width: 100%;
    min-height: 28px;
    gap: 4px;
    margin: 0;
    padding: 0;
    float: none;
    filter: none;
    transition: none;
}
body #chat .ch_name .mes_edit_buttons { max-width: calc(100% + 56px); margin-right: -56px; }
/* CSS-only themes retain the native avatar parent; give it its own column. */
body:not(.cu-shell-ready) #chat .mes { display: flex; gap: 10px; }
body:not(.cu-shell-ready) #chat .mes > .mesAvatarWrapper { position: static; flex: 0 0 24px; height: auto; padding: 0; }
body:not(.cu-shell-ready) #chat .mes > .mes_block { flex: 1; min-width: 0; }
body:not(.cu-shell-ready) #chat .mes .ch_name { grid-template-columns: minmax(0,1fr); }
body:not(.cu-shell-ready) #chat .mes .ch_name > .flex-container.flex1 { grid-column: 1; }
body #chat .ch_name :is(.mes_button,.mes_edit_buttons .menu_button) {
    width: 28px; height: 28px; min-height: 28px; margin: 0; padding: 6px;
    font-size: 13px; line-height: 16px; border: 0; border-radius: 7px;
    opacity: .85; color: var(--cu-muted); background: transparent; box-shadow: none;
}
body #chat .mes:has(#curEditTextarea) :is(.swipe_left,.swipeRightBlock) { visibility: hidden; }
body #chat #curEditTextarea {
    display: block;
    width: 100%;
    min-height: var(--cu-edit-min-height,1lh);
    max-height: none;
    padding: 0;
    margin: 0;
    border: 0 !important;
    border-radius: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    line-height: inherit;
    letter-spacing: inherit;
    box-shadow: none;
    field-sizing: content;
}
body #chat #curEditTextarea:focus-visible { outline: none !important; }
body #chat :is(pre,.hljs) { background: var(--cu-code) !important; color: var(--cu-text); border: 1px solid var(--cu-border); border-radius: 10px; font-size: 13px; text-wrap: nowrap; overflow-x: auto; }
body #chat pre { padding: 16px; max-width: 100%; }
body #chat pre .hljs { border: 0; border-radius: 0; padding: 0; background: transparent !important; }
body #chat pre :is(.hljs-keyword,.hljs-selector-tag,.hljs-literal) { color: var(--cu-syntax-keyword); }
body #chat pre :is(.hljs-string,.hljs-attr) { color: var(--cu-syntax-string); }
body #chat pre :is(.hljs-title,.hljs-built_in,.hljs-function) { color: var(--cu-syntax-title); }
body #chat pre .hljs-number { color: var(--cu-syntax-number); }
body #chat pre .hljs-comment { color: var(--cu-syntax-comment); }
body #chat code { font-family: "Cascadia Code", Consolas, monospace; }
body #chat :not(pre)>code { padding: 2px 5px; background: var(--cu-hover); border: 1px solid var(--cu-border); border-radius: 4px; font-size: .88em; }
body #chat blockquote { border-left: 3px solid var(--cu-border); background: transparent; color: var(--cu-muted); margin: 16px 0; padding: 0 16px; }
body #chat table { display: block; overflow-x: auto; width: 100%; border-collapse: collapse; font-family: var(--cu-sans); font-size: 14px; }
body #chat :is(th,td) { border-color: var(--cu-border); padding: 10px; }
body .mes_reasoning_details { margin: 0 0 12px; border-color: var(--cu-border); color: var(--cu-muted); font-family: var(--cu-sans); }
body #form_sheld { flex: 0 0 auto; width: min(768px,100%); margin: 0 auto; padding: 0 16px max(12px, env(safe-area-inset-bottom)); background: var(--cu-bg); }
body #send_form { padding: 8px; border: 1px solid var(--cu-input-border) !important; border-radius: 14px; background: var(--cu-input) !important; box-shadow: 0 4px 20px #00000009; backdrop-filter: none; }
body #send_form:has(#send_textarea:focus-visible) { outline: none !important; border-color: var(--cu-muted) !important; box-shadow: inset 0 0 0 1px var(--cu-muted); }
body #nonQRFormItems { display: grid !important; grid-template-columns: 1fr auto; align-items: end; gap: 4px; }
body #send_textarea { grid-column: 1 / -1; grid-row: 1; width: 100% !important; min-height: 32px; max-height: min(32dvh,240px); margin: 0; padding: 5px 8px; border: 0 !important; border-radius: 0; outline: none; background: transparent !important; box-shadow: none; color: var(--cu-text); font-size: 16px !important; line-height: 22px; resize: none; }
body #send_textarea::placeholder { color: var(--cu-muted); opacity: 1; text-align: left; font-style: normal; font-weight: 400; }
body #leftSendForm { grid-column: 1; grid-row: 2; display: flex; align-items: center; gap: 2px; width: auto; min-width: 0; }
body #rightSendForm { grid-column: 2; grid-row: 2; display: flex; width: auto; gap: 2px; align-items: center; }
body :is(#options_button,#extensionsMenuButton,#send_but,#mes_continue,#mes_impersonate,#mes_stop,.stscript_btn) { min-width: 32px; min-height: 32px; padding: 8px; border-radius: 8px; color: var(--cu-text); font-size: 16px; margin: 0; }
body #send_but { background: var(--cu-text); color: var(--cu-bg); }
body #send_but::before { content: "\f062"; }
body #options_button::before { content: "\f141"; }
body #qr--bar { padding: 0 0 8px; }
body :is(.drawer-content,.popup,#options,#extensionsMenu,#select_chat_popup,#dialogue_popup,.floating_panel,.list-group,.ui-autocomplete) { color: var(--cu-text); background: var(--cu-surface) !important; border: 1px solid var(--cu-border); border-radius: 14px; box-shadow: 0 8px 32px #0002; backdrop-filter: none; }
body :is(.drawer-content,.popup,.floating_panel) :is(h2,h3,h4,.standoutHeader) { color: var(--cu-text); }
body :is(.text_pole,select,textarea,input[type="text"],input[type="number"],input[type="search"],input[type="password"]) { color: var(--cu-text); background-color: var(--cu-hover); border: 1px solid var(--cu-border); border-radius: 7px; box-shadow: none; }
body :is(input[type="checkbox"],input[type="radio"],input[type="range"]) { accent-color: var(--cu-accent); }
body :is(.menu_button,.menu_button_icon) { color: var(--cu-text); background: var(--cu-hover); border-color: var(--cu-border); border-radius: 7px; box-shadow: none; }
body :is(.menu_button,.menu_button_icon):hover { background: var(--cu-selected); }
body :is(.inline-drawer-toggle,.inline-drawer-header) { background: transparent; border-color: var(--cu-border); border-radius: 8px; }
body #options { background: transparent !important; border: 0; box-shadow: none; }
body #options .options-content { background: var(--cu-surface); border: 1px solid var(--cu-border); border-radius: 12px; padding: 5px; }
body :is(#options .options-content a,#extensionsMenu>div:not(.extension_container),#extensionsMenu>.extension_container>div) { color: var(--cu-text); opacity: 1; min-height: 36px; padding: 8px 10px; font-size: 14px; border-radius: 7px; }
body :is(#options .options-content a,#extensionsMenu>div):hover { background: var(--cu-hover); }
body #toast-container>.toast { background: var(--cu-surface) !important; color: var(--cu-text); border: 1px solid var(--cu-border); border-radius: 10px; box-shadow: 0 6px 24px #0002; }
body .inline-drawer-content { border-color: var(--cu-border); }
/* Native SillyTavern forms: typography, sections and interactive controls share
   the same quiet surfaces as the shell; the original elements stay in place. */
body :is(.drawer-content,.popup,.floating_panel,#select_chat_popup,#dialogue_popup) {
    font-family: var(--cu-sans); font-size: 14px; font-weight: 400; line-height: 1.55;
}
body :is(.drawer-content,.popup,.floating_panel) :is(h1,h2,h3,h4,legend,.title_restorable,.standoutHeader,.range-block-title,.inline-drawer-header) {
    font-family: var(--cu-sans); color: var(--cu-text); letter-spacing: 0;
    text-transform: none; text-align: start; line-height: 1.5;
}
body :is(.drawer-content,.popup,.floating_panel) :is(h1,h2) { font-size: 18px; font-weight: 600; margin: 0 0 14px; }
body :is(.drawer-content,.popup,.floating_panel) h3 { font-size: 15px; font-weight: 600; margin: 14px 0 10px; }
body :is(.drawer-content,.popup,.floating_panel) h4 { font-size: 14px; font-weight: 500; margin: 12px 0 8px; }
body :is(.drawer-content,.popup,.floating_panel) :is(b,strong) { font-weight: 600; }
body :is(.drawer-content,.popup,.floating_panel) :is(label,.range-block-title) { font-size: 13px; font-weight: 400; }
body :is(.drawer-content,.popup,.floating_panel) :is(small,.notes,.note,.description) { color: var(--cu-muted); font-size: 12px; line-height: 1.5; }
body :is(.drawer-content,.popup,.floating_panel) :is(.standoutHeader,.inline-drawer-header),
body #user-settings-block h4 {
    background: transparent !important; background-image: none !important;
    border: 0 !important; border-bottom: 1px solid var(--cu-border) !important;
    border-radius: 0; box-shadow: none; filter: none !important;
    padding: 11px 0; margin: 8px 0; font-size: 13px; font-weight: 600;
}
body :is(.drawer-content,.popup,.floating_panel) .inline-drawer-content {
    background: transparent !important; background-image: none !important;
    border: 0; box-shadow: none; padding: 4px 0 12px;
}
body :is(.drawer-content,.popup,.floating_panel) .inline-drawer-icon {
    background: transparent; color: var(--cu-muted); border: 0; border-radius: 6px;
    font-size: 12px; width: 24px; height: 24px; line-height: 24px; text-align: center;
}
body .inline-drawer-icon.fa-circle-chevron-down::before { content: "\f078"; }
body .inline-drawer-icon.fa-circle-chevron-up::before { content: "\f077"; }
body :is(.drawer-content,.popup,.floating_panel) .range-block { padding: 10px 0; margin: 0; gap: 7px; min-width: 0; }
body :is(.drawer-content,.popup,.floating_panel) .range-block-title { text-align: start !important; color: var(--cu-text); margin: 0 0 3px; }
body :is(.drawer-content,.popup,.floating_panel) :is(input.text_pole,input[type="text"],input[type="number"],input[type="search"],input[type="password"],input[type="url"],select) {
    min-height: 34px; max-width: 100%; padding: 6px 10px;
    background: var(--cu-input); color: var(--cu-text); font-size: 13px; font-weight: 400;
    line-height: 20px; border: 1px solid var(--cu-border); border-radius: 8px; box-shadow: none;
}
body :is(.drawer-content,.popup,.floating_panel) textarea {
    padding: 10px 12px; font: 14px/1.6 var(--cu-sans); color: var(--cu-text);
    background: var(--cu-input); border: 1px solid var(--cu-border); border-radius: 10px;
}
body :is(.drawer-content,.popup,.floating_panel) :is(input,textarea)::placeholder { color: var(--cu-muted) !important; font-size: 13px; opacity: 1; text-align: start; }
body :is(.drawer-content,.popup,.floating_panel) option { color: var(--cu-text); background: var(--cu-surface); }
body :is(.drawer-content,.popup,.floating_panel) :is(.menu_button,.menu_button_icon) {
    background: transparent; background-image: none; color: var(--cu-text);
    border: 1px solid var(--cu-border); border-radius: 7px;
    min-height: 28px; padding: 4px 7px; line-height: 18px;
    font-size: 13px; font-weight: 400; box-shadow: none; filter: none;
}
body :is(.drawer-content,.popup,.floating_panel) :is(.menu_button,.menu_button_icon):hover { background: var(--cu-hover); border-color: var(--cu-muted); }
body :is(.drawer-content,.popup,.floating_panel) .checkbox_label { min-height: 28px; align-items: flex-start; column-gap: 7px; line-height: 22px; }
body :is(input[type="checkbox"],input[type="radio"]) {
    appearance: none; -webkit-appearance: none; position: relative;
    width: 16px; height: 16px; min-width: 16px; min-height: 16px; flex: 0 0 16px;
    padding: 0; margin: 3px 4px 3px 0; vertical-align: middle;
    background: var(--cu-input); color: var(--cu-bg);
    border: 1px solid var(--cu-muted); border-radius: 4px; box-shadow: none; cursor: pointer;
}
body input[type="checkbox"]:checked { border-color: var(--cu-text); background: var(--cu-text); }
body input[type="checkbox"]:checked::after { content: "✓"; position: absolute; inset: 0; display: grid; place-items: center; font: 700 12px/1 Arial,sans-serif; color: var(--cu-bg); }
body input[type="checkbox"]:indeterminate::after { content: "−"; position: absolute; inset: 0; display: grid; place-items: center; font: 14px/1 Arial,sans-serif; color: var(--cu-text); }
body input[type="radio"] { border-radius: 50%; }
body input[type="radio"]:checked::after { content: ""; position: absolute; inset: 0; margin: auto; width: 8px; height: 8px; border-radius: 50%; background: var(--cu-text); }
body :is(input[type="checkbox"],input[type="radio"])[hidden] { display: none; }
body input[type="range"] {
    appearance: none; -webkit-appearance: none; height: 22px; min-height: 22px;
    padding: 0; margin: 0; background: transparent; border: 0; box-shadow: none;
}
body input[type="range"]::-webkit-slider-runnable-track { height: 3px; border-radius: 2px; background: var(--cu-border); }
body input[type="range"]::-webkit-slider-thumb {
    appearance: none; -webkit-appearance: none; width: 12px; height: 12px;
    margin-top: -4.5px; border: 2px solid var(--cu-surface); border-radius: 50%;
    background: var(--cu-text); box-shadow: 0 0 0 1px var(--cu-border); cursor: grab;
}
body input[type="range"]::-moz-range-track { height: 3px; border-radius: 2px; background: var(--cu-border); }
body input[type="range"]::-moz-range-thumb { width: 9px; height: 9px; border: 2px solid var(--cu-surface); border-radius: 50%; background: var(--cu-text); }
body .range-block-counter input { min-height: 30px; padding: 4px 6px; font-size: 12px; font-variant-numeric: tabular-nums; text-align: center; }
body :is(.drawer-content,.popup,.floating_panel) :is(input,select,textarea,button):disabled { opacity: .45; cursor: default; }
body :is(.drawer-content,.popup,.floating_panel) :is(.character_select,.group_select,.avatar-container) { border-color: var(--cu-border); border-radius: 10px; box-shadow: none; }
