@media (max-width: 899px) {
    .cu-sheet-panel::before { display: none; }
    .cu-sheet-handle { display: grid; place-items: center; width: 64px; height: 22px; padding: 8px 14px; margin: -12px auto 10px; touch-action: none; cursor: grab; flex-shrink: 0; }
    .cu-sheet-handle svg { display: none; }
    .cu-sheet-handle::after { content: ''; width: 36px; height: 4px; border-radius: 4px; background: var(--cu-border); }
    .cu-sheet-panel { animation-name: cu-sheet-mobile-in; }
    .cu-sheet-closing .cu-sheet-panel { animation-name: cu-sheet-mobile-out; }
    body .cu-range-row { flex-basis: 100%; }
    @keyframes cu-sheet-mobile-in { from { opacity: 0; transform: translateY(100%); } to { opacity: 1; transform: translateY(0); } }
    @keyframes cu-sheet-mobile-out { to { opacity: 0; transform: translateY(100%); } }
}
@media (prefers-reduced-motion: reduce) {
    .cu-sheet,.cu-sheet-panel,.cu-sheet-closing,.cu-sheet-closing .cu-sheet-panel,body.cu-shell-ready #top-settings-holder > .drawer > .openDrawer { animation: none !important; transition: none !important; }
}

